package mz.gov.mogovolas.expedientes.security;
import org.springframework.context.annotation.*; import org.springframework.security.config.annotation.method.configuration.EnableMethodSecurity; import org.springframework.security.config.annotation.web.builders.HttpSecurity; import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.security.web.SecurityFilterChain;
@Configuration @EnableMethodSecurity public class SecurityConfig { @Bean PasswordEncoder passwordEncoder(){return new BCryptPasswordEncoder(12);} @Bean SecurityFilterChain security(HttpSecurity h)throws Exception{ h.authorizeHttpRequests(a->a.requestMatchers("/login","/css/**","/js/**","/api/public/**","/actuator/health").permitAll().anyRequest().authenticated()).formLogin(f->f.loginPage("/login").defaultSuccessUrl("/",true).permitAll()).logout(l->l.logoutSuccessUrl("/login?logout").permitAll()).csrf(c->c.ignoringRequestMatchers("/api/**")).sessionManagement(s->s.sessionFixation().migrateSession().maximumSessions(2)); return h.build(); } }
